import{_ as t,o as a,c as s,ag as d}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Student Dashboard -> Messages / Chat (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/student-dashboard/messages-chat.md","filePath":"modules/student-dashboard/messages-chat.md"}'),o={name:"modules/student-dashboard/messages-chat.md"};function r(i,e,n,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="student-dashboard-messages-chat-deep" tabindex="-1">Student Dashboard -&gt; Messages / Chat (deep) <a class="header-anchor" href="#student-dashboard-messages-chat-deep" aria-label="Permalink to &quot;Student Dashboard -&gt; Messages / Chat (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>student-dashboard</code><br><strong>Feature:</strong> <code>messages-chat</code><br><strong>Route:</strong> <code>/student-dashboard/chat</code></p><p>This feature is the student chat interface for messaging instructors. It combines GraphQL message history, subscriptions, Redux unread state, and Socket.IO live behavior for typing and session updates.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Let students chat directly with instructors they are connected to through bookings.</li><li>Show message history and unread state.</li><li>Provide real-time updates and typing indicators.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/student-dashboard/chat/index.tsx</code></td><td>Main student chat page</td><td>Loads/coordinates selected conversation, message list, and send-message actions.</td></tr><tr><td><code>Frontend/src/components/Chat/ChatList.tsx</code></td><td>Conversation list</td><td>Displays available instructor conversations.</td></tr><tr><td><code>Frontend/src/components/Chat/ChatWindow.tsx</code></td><td>Message pane</td><td>Shows messages, composer, and typing state.</td></tr><tr><td><code>Frontend/src/components/Chat/MessageItem.tsx</code></td><td>Individual message row</td><td>Formats message bubble content and sender metadata.</td></tr><tr><td><code>Frontend/src/store/slices/chatSlice.ts</code></td><td>Redux chat state</td><td>Tracks unread counts, selected conversation, and related chat UI state.</td></tr><tr><td><code>Frontend/src/utils/socket.ts</code></td><td>Socket.IO client helper</td><td>Handles real-time message-related transport outside pure GraphQL.</td></tr><tr><td><code>Frontend/src/hooks/useSockets.ts</code></td><td>Socket bootstrap</td><td>Integrates authenticated socket behavior into the dashboard shell.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="message-history" tabindex="-1">Message history <a class="header-anchor" href="#message-history" aria-label="Permalink to &quot;Message history&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/Chat.ts</code></li><li>Query field: <ul><li><code>GET_MESSAGES</code> → <code>getMessages(user1Id, user2Id)</code></li></ul></li></ul><h3 id="send-message" tabindex="-1">Send message <a class="header-anchor" href="#send-message" aria-label="Permalink to &quot;Send message&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/Chat.ts</code></li><li>Mutation field: <ul><li><code>SEND_MESSAGE</code> → <code>sendMessage(...)</code></li></ul></li></ul><h3 id="realtime-graphql-subscription" tabindex="-1">Realtime GraphQL subscription <a class="header-anchor" href="#realtime-graphql-subscription" aria-label="Permalink to &quot;Realtime GraphQL subscription&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/Chat.ts</code></li><li>Subscription field: <ul><li><code>NEW_MESSAGE_SUBSCRIPTION</code> → <code>messageSent(user1Id, user2Id)</code></li></ul></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/chat.typeDefs.js</code></li><li>Relevant fields: <ul><li><code>getMessages</code></li><li><code>sendMessage</code></li><li><code>messageSent</code></li><li>declared conversation-related shapes used by the chat schema</li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/chat.resolvers.js</code></li><li>Relevant resolvers: <ul><li><code>Query.getMessages</code></li><li><code>Mutation.sendMessage</code></li><li><code>Subscription.messageSent</code></li></ul></li><li>The chat page also depends on booking-derived instructor lists built elsewhere in the frontend layout flow.</li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/Message.js</code></td><td>Persisted message history</td></tr><tr><td><code>server/src/models/Conversation.js</code></td><td>Conversation model</td></tr><tr><td><code>server/src/socket/index.js</code></td><td>Socket.IO server bootstrap and real-time transport</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Booking relationships reused to infer valid student/instructor chat surfaces</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Student opens <code>/student-dashboard/chat</code>.</li><li>Layout/chat state determines which instructor conversations are available (derived from booked instructors and stored chat state).</li><li><code>getMessages</code> loads message history for the selected conversation pair.</li><li>Sending a message calls <code>sendMessage</code>.</li><li>New messages appear through the GraphQL subscription and Socket.IO-driven realtime updates.</li><li>Redux unread state is cleared/updated as the student enters or leaves active conversations.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>The student chat page does not rely on a fully mature dedicated “get all conversations” GraphQL path; conversation sourcing is partly derived from bookings and local chat state.</li><li>Chat is one of the most shared modules across student and teacher dashboards, so UI or schema changes here usually affect both sides.</li><li>Socket.IO and GraphQL subscriptions coexist in this feature; tracing live-message bugs often requires checking both.</li></ul>',25)])])}const g=t(o,[["render",r]]);export{p as __pageData,g as default};
